#[test]
fn pascal_seconds_per_liter() {
    for v in [1.0, 0.3, -42.75, 1e6, 123456.789] {
        // Generated conversion vs. the upstream formula, verbatim.
        let x: f64 = v;
        let base = x * 1e3;
        assert_close(
            FluidResistance::from_pascal_seconds_per_liter(v).as_base(),
            base,
            F64_TOL,
        );
        let x: f64 = base;
        let back = x / 1e3;
        assert_close(
            FluidResistance::from_base(base).as_pascal_seconds_per_liter(),
            back,
            F64_TOL,
        );
        assert_close(
            FluidResistance::from_pascal_seconds_per_liter(v).as_pascal_seconds_per_liter(),
            v,
            ROUND_TRIP_TOL,
        );
        // f32 storage.
        assert_close(
            FluidResistance::from_pascal_seconds_per_liter(v as f32).as_base() as f64,
            base,
            F32_TOL,
        );
        assert_close(
            FluidResistance::from_base(base as f32).as_pascal_seconds_per_liter() as f64,
            back,
            F32_TOL,
        );
    }
}

