#[test]
fn wood_units() {
    for v in [1.0, 0.3, -42.75, 1e6, 123456.789] {
        // Generated conversion vs. the upstream formula, verbatim.
        let x: f64 = v;
        let base = x * 7.99934208e6;
        assert_close(FluidResistance::from_wood_units(v).as_base(), base, F64_TOL);
        let x: f64 = base;
        let back = x / 7.99934208e6;
        assert_close(
            FluidResistance::from_base(base).as_wood_units(),
            back,
            F64_TOL,
        );
        assert_close(
            FluidResistance::from_wood_units(v).as_wood_units(),
            v,
            ROUND_TRIP_TOL,
        );
        // f32 storage.
        assert_close(
            FluidResistance::from_wood_units(v as f32).as_base() as f64,
            base,
            F32_TOL,
        );
        assert_close(
            FluidResistance::from_base(base as f32).as_wood_units() as f64,
            back,
            F32_TOL,
        );
    }
}

